<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Color HEX Preview','description'=>'Preview a HEX color and copy its CSS value.','url'=>'https://smarttoolz.in/tools/color-hex-preview/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>Color HEX Preview</h1><p>Enter a HEX value and preview it instantly.</p></section><section class="tool-workspace"><div class="tool-panel"><input id="c" value="#5b43ff" maxlength="7"><div id="p" style="height:180px;border-radius:14px;margin-top:15px"></div><p id="o"></p><button id="copy" class="tool-btn">Copy HEX</button></div></section></main><script>function go(){let v=c.value.trim();if(/^#[0-9a-f]{6}$/i.test(v)){p.style.background=v;o.textContent=v}else o.textContent='Enter a valid 6-digit HEX color.'}c.oninput=go;copy.onclick=()=>navigator.clipboard.writeText(c.value);go()</script><?php smarttoolz_tool_page_end(); ?>